  const imageLayer=(href,x,y,w,h)=>{const n=document.createElementNS('http://www.w3.org/2000/svg','image');for(const [k,v] of Object.entries({href,x,y,width:w,height:h}))n.setAttribute(k,v);return n;};
  const artPaintTokens=new WeakMap();
  const renderArt=(svg,art)=>{if(svg.tagName==='IMG'){if(svg.getAttribute('src')!==art.preview)svg.src=art.preview;svg.alt=art.title;return;}const token={};artPaintTokens.set(svg,token);svg.replaceChildren(imageLayer(art.preview,0,0,art.width,art.height));if(svg.dataset.full!=='true')return;const sources=[art.baseImage,art.common?.src,art.patch?.src].filter(Boolean);Promise.all(sources.map(loadImage)).then(()=>{if(artPaintTokens.get(svg)!==token||!svg.isConnected)return;const group=document.createElementNS('http://www.w3.org/2000/svg','g');group.append(imageLayer(art.baseImage,0,0,art.width,art.height));for(const p of [art.common,art.patch])if(p)group.append(imageLayer(p.src,p.x,p.y,p.width,p.height));svg.append(group);}).catch(()=>{});};
  window.paintGalleryArtwork=renderArt;
  const loadImage=src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('Artwork asset unavailable'));im.src=src;});
  const exportArt=async(n,art)=>{const button=document.querySelector('.lb-download'),label=button?.textContent;if(button){button.disabled=true;button.textContent=mediaLanguage()==='pt'?'Preparando PNG…':'Preparing PNG…';}try{const [base,common,patch]=await Promise.all([loadImage(art.baseImage),art.common?loadImage(art.common.src):null,art.patch?loadImage(art.patch.src):null]);const canvas=document.createElement('canvas');canvas.width=art.width;canvas.height=art.height;const ctx=canvas.getContext('2d',{alpha:false});ctx.drawImage(base,0,0);if(common)ctx.drawImage(common,art.common.x,art.common.y);if(patch)ctx.drawImage(patch,art.patch.x,art.patch.y);const blob=await new Promise((ok,fail)=>canvas.toBlob(b=>b?ok(b):fail(new Error('PNG export failed')),'image/png'));const url=URL.createObjectURL(blob);download(url,'jennifer-evangelista-artwork-'+String(n).padStart(3,'0')+'.png');setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(error){let notice=document.getElementById('galleryDownloadStatus');if(!notice){notice=document.createElement('p');notice.id='galleryDownloadStatus';notice.setAttribute('role','alert');document.querySelector('.lb-content,.lb-inner,#lightbox')?.append(notice);}notice.textContent=mediaLanguage()==='pt'?'Não foi possível preparar a arte. Tente novamente.':'Could not prepare the artwork. Please try again.';}finally{if(button){button.disabled=false;button.textContent=label;}}};

  window.getGalleryArtwork=n=>{const original=artworks[String(n)],layer=compactArt[String(n)];if(!original||!layer)return null;const lang=mediaLanguage(),suffix=String(n).padStart(3,'0');const preview=lang==='en'?original.preview:'assets/gallery-artworks/'+lang+'/gallery-'+suffix+'-preview.webp?v=20261029-fast';return {...original,image:preview,preview,baseImage:layer.base,width:layer.width,height:layer.height,patch:layer.patches[lang]||null,common:layer.common||null};};
  const updateArtworkLanguage=()=>{document.querySelectorAll('.mf-banner-svg[data-artwork]').forEach(svg=>{const art=window.getGalleryArtwork(svg.dataset.artwork);if(art)renderArt(svg,art);});};
  document.addEventListener('jen:languagechange',updateArtworkLanguage);

  window.JENNIFER_GALLERY_ARTWORKS=Object.freeze(artworks);
  const download=(href,name)=>{const a=document.createElement('a');a.href=href;a.download=name;document.body.append(a);a.click();a.remove();};
  window.downloadGalleryArtwork=n=>{const art=window.getGalleryArtwork(n);if(!art)return false;exportArt(n,art);return true;};
  window.downloadSharedContactCard=()=>download(cardForLanguage().pdf,`jennifer-evangelista-contact-card-${mediaLanguage()}.pdf`);
  const container=document.getElementById('contactCards');if(!container)return;
  container.setAttribute('data-no-translate','');
  const copy={
    pt:{heading:'Cartão de contato',front:'Frente · clique para virar ↻',back:'Verso · clique para voltar ↻',showBack:'Virar cartão para ver o verso',showFront:'Virar cartão para ver a frente',download:'Baixar cartão (PDF)'},
    en:{heading:'Contact card',front:'Front · click to flip ↻',back:'Back · click to return ↻',showBack:'Flip the card to see the back',showFront:'Flip the card to see the front',download:'Download card (PDF)'},
    es:{heading:'Tarjeta de contacto',front:'Frente · pulsa para girar ↻',back:'Reverso · pulsa para volver ↻',showBack:'Girar la tarjeta para ver el reverso',showFront:'Girar la tarjeta para ver el frente',download:'Descargar tarjeta (PDF)'},
    ja:{heading:'連絡先カード',front:'表面 · クリックして裏返す ↻',back:'裏面 · クリックして戻す ↻',showBack:'カードを裏返して裏面を見る',showFront:'カードを裏返して表面を見る',download:'カードをダウンロード (PDF)'}
  };
  const heading=document.createElement('h3');
  const figure=document.createElement('figure');figure.className='contact-card-tile';
  const preview=document.createElement('button');preview.type='button';preview.className='contact-card-preview';preview.setAttribute('aria-pressed','false');preview.setAttribute('aria-describedby','contactCardHint');
  const flipper=document.createElement('span');flipper.className='contact-card-flipper';
  const faces=[];
  for(const [src,side] of [[card.image,'front'],[card.back,'back']]){
    const face=document.createElement('span');face.className='contact-card-face contact-card-face--'+side;face.setAttribute('aria-hidden',String(side==='back'));
    const im=document.createElement('img');im.src=src;im.alt=side==='front'?'Jennifer Evangelista contact card: email, website and Linktree':'Jennifer Evangelista contact card: Pix';im.width=600;im.height=343;im.loading='lazy';face.append(im);flipper.append(face);faces.push(face);
  }
  preview.append(flipper);
  const caption=document.createElement('figcaption');caption.id='contactCardHint';caption.setAttribute('aria-live','polite');figure.append(preview,caption);
  const links=document.createElement('div');links.className='contact-card-links';const a=document.createElement('a');a.href=card.pdf;a.download='jennifer-evangelista-contact-card.pdf';links.append(a);
  let flipped=false;
  const update=()=>{
    card=cardForLanguage();faces[0].querySelector('img').src=card.image;a.href=card.pdf;a.download=`jennifer-evangelista-contact-card-${mediaLanguage()}.pdf`;
    const language=document.documentElement.lang.slice(0,2).toLowerCase();const text=copy[language]||copy.pt;
    if(heading.textContent!==text.heading)heading.textContent=text.heading;
    const hint=flipped?text.back:text.front;if(caption.textContent!==hint)caption.textContent=hint;
    if(a.textContent!==text.download)a.textContent=text.download;
    preview.classList.toggle('is-flipped',flipped);
    const attributes={'aria-pressed':String(flipped),'aria-label':flipped?text.showFront:text.showBack};
    for(const [name,value] of Object.entries(attributes))if(preview.getAttribute(name)!==value)preview.setAttribute(name,value);
    for(const [index,hidden] of [[0,flipped],[1,!flipped]])if(faces[index].getAttribute('aria-hidden')!==String(hidden))faces[index].setAttribute('aria-hidden',String(hidden));
  };
  preview.addEventListener('click',()=>{flipped=!flipped;update();});
  document.addEventListener('jen:languagechange',update);
  document.addEventListener('portfolio:languagechange',update);
  container.replaceChildren(heading,figure,links);update();
  const prewarm=()=>{for(const src of [cardForLanguage().image,cardForLanguage().back]){const im=new Image();im.src=src;}};
  if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){prewarm();observer.disconnect();}},{rootMargin:'900px'});observer.observe(container);}else prewarm();
